    check_fixture_contracts()?;
    check_traceability()?;
    check_capabilities()?;
    check_workspace_shape()?;
    check_architecture()?;
    check_public_api()?;
    check_output_contracts()?;
    check_doc_artifacts()?;
    check_doc_index()?;
    check_readme_state()?;
    markdown_links()?;
    check_pr_shape()?;
    check_command_catalog()?;
    check_generated()?;
    check_badge_diff_policy()?;
    check_generated_clean()?;
    check_proof_packs()?;
    check_dependencies()?;
