    pr_first_string_path(
        packet,
        &[
            &["suggested_test_file"],
            &["repair_card", "suggested_test_file"],
            &["repair_route", "target_file"],
        ],
    )
    .or_else(|| pr_first_string_array_path(packet, &["allowed_files"]))
    .or_else(|| pr_first_string_array_path(packet, &["allowed_edit_surface"]))
