fn matches_any_glob(allowlist: &[GlobAllow], path: &str) -> bool {
    allowlist
        .iter()
        .any(|entry| glob_matches(&entry.glob, path))
}

fn glob_matches(pattern: &str, path: &str) -> bool {
    let pattern_parts = pattern.split('/').collect::<Vec<_>>();
    let path_parts = path.split('/').collect::<Vec<_>>();
    glob_parts_match(&pattern_parts, &path_parts)
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum StaticLanguageMatcher {
    Path(String),
    Glob(String),
}

impl StaticLanguageMatcher {
    fn as_str(&self) -> &str {
        match self {
            StaticLanguageMatcher::Path(value) | StaticLanguageMatcher::Glob(value) => value,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StaticLanguageAllowEntry {
    matcher: StaticLanguageMatcher,
    owner: String,
    reason: String,
}

#[cfg(test)]
impl StaticLanguageAllowEntry {
    fn new_path(
        path: impl Into<String>,
        owner: impl Into<String>,
        reason: impl Into<String>,
    ) -> Self {
        Self {
            matcher: StaticLanguageMatcher::Path(path.into()),
            owner: owner.into(),
            reason: reason.into(),
        }
    }

    fn new_glob(
        glob: impl Into<String>,
        owner: impl Into<String>,
        reason: impl Into<String>,
    ) -> Self {
        Self {
            matcher: StaticLanguageMatcher::Glob(glob.into()),
            owner: owner.into(),
            reason: reason.into(),
        }
    }
}

const STATIC_LANGUAGE_ALLOWLIST_PATH: &str = ".ripr/static-language-allowlist.toml";
const STATIC_LANGUAGE_ALLOWLIST_LEGACY_PATH: &str = ".ripr/static-language-allowlist.txt";
const STATIC_LANGUAGE_ALLOWED_GLOBS: &[&str] = &["docs/*.md", "docs/**/*.md"];

fn parse_static_language_allowlist(text: &str) -> (Vec<StaticLanguageAllowEntry>, Vec<String>) {
    let mut entries: Vec<StaticLanguageAllowEntry> = Vec::new();
    let mut violations = Vec::new();
    let mut schema_seen = false;
    let mut current: Option<PendingAllowEntry> = None;

    for (index, line) in text.lines().enumerate() {
        let line_number = index + 1;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if trimmed == "[[allow]]" {
            if let Some(pending) = current.take() {
                finalize_static_language_entry(pending, &mut entries, &mut violations);
            }
            current = Some(PendingAllowEntry::new(line_number));
            continue;
        }
        let Some((key, raw_value)) = trimmed.split_once('=') else {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} expected `key = value`"
            ));
            continue;
        };
        let key = key.trim();
        let raw_value = raw_value.trim();
        if let Some(pending) = current.as_mut() {
            match key {
                "path" => assign_static_language_field(
                    raw_value,
                    line_number,
                    &mut violations,
                    |parsed| pending.path = Some((parsed, line_number)),
                ),
                "glob" => assign_static_language_field(
                    raw_value,
                    line_number,
                    &mut violations,
                    |parsed| pending.glob = Some((parsed, line_number)),
                ),
                "owner" => assign_static_language_field(
                    raw_value,
                    line_number,
                    &mut violations,
                    |parsed| pending.owner = Some((parsed, line_number)),
                ),
                "reason" => assign_static_language_field(
                    raw_value,
                    line_number,
                    &mut violations,
                    |parsed| pending.reason = Some((parsed, line_number)),
                ),
                _ => violations.push(format!(
                    "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} unsupported `[[allow]]` field `{key}`"
                )),
            }
        } else if key == "schema_version" {
            schema_seen = true;
            match raw_value.parse::<u32>() {
                Ok(1) => {}
                Ok(other) => violations.push(format!(
                    "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} schema_version = {other} is not supported (expected 1)"
                )),
                Err(_) => violations.push(format!(
                    "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} schema_version must be an integer literal"
                )),
            }
        } else {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} unsupported top-level field `{key}`"
            ));
        }
    }

    if let Some(pending) = current.take() {
        finalize_static_language_entry(pending, &mut entries, &mut violations);
    }

    if !schema_seen {
        violations.push(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH} is missing required `schema_version = 1` header"
        ));
    }

    let mut seen_matchers: BTreeMap<&str, usize> = BTreeMap::new();
    for entry in &entries {
        let matcher = entry.matcher.as_str();
        if let Some(&first) = seen_matchers.get(matcher) {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH} matcher `{matcher}` is duplicated (first declared near line {first})"
            ));
        } else {
            seen_matchers.insert(matcher, 0);
        }
    }

    (entries, violations)
}

struct PendingAllowEntry {
    block_line: usize,
    path: Option<(String, usize)>,
    glob: Option<(String, usize)>,
    owner: Option<(String, usize)>,
    reason: Option<(String, usize)>,
}

impl PendingAllowEntry {
    fn new(block_line: usize) -> Self {
        Self {
            block_line,
            path: None,
            glob: None,
            owner: None,
            reason: None,
        }
    }
}

fn assign_static_language_field<F>(
    raw_value: &str,
    line_number: usize,
    violations: &mut Vec<String>,
    mut assign: F,
) where
    F: FnMut(String),
{
    match parse_quoted_value(raw_value) {
        Ok(parsed) => assign(parsed),
        Err(message) => violations.push(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} {message}"
        )),
    }
}

fn finalize_static_language_entry(
    pending: PendingAllowEntry,
    entries: &mut Vec<StaticLanguageAllowEntry>,
    violations: &mut Vec<String>,
) {
    let block_line = pending.block_line;
    let path_value = pending.path;
    let glob_value = pending.glob;
    let owner_value = pending.owner;
    let reason_value = pending.reason;

    let matcher = match (path_value, glob_value) {
        (Some((path, line)), None) => match validate_static_language_path(&path, line) {
            Ok(()) => Some(StaticLanguageMatcher::Path(path)),
            Err(message) => {
                violations.push(message);
                None
            }
        },
        (None, Some((glob, line))) => match validate_static_language_glob(&glob, line) {
            Ok(()) => Some(StaticLanguageMatcher::Glob(glob)),
            Err(message) => {
                violations.push(message);
                None
            }
        },
        (Some(_), Some(_)) => {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{block_line} `[[allow]]` entry has both `path` and `glob`; declare exactly one"
            ));
            None
        }
        (None, None) => {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{block_line} `[[allow]]` entry must declare either `path` or `glob`"
            ));
            None
        }
    };

    let owner = match owner_value {
        Some((value, line)) => {
            if value.trim().is_empty() {
                violations.push(format!(
                    "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line} `owner` is blank; name a responsible team or maintainer"
                ));
                None
            } else {
                Some(value)
            }
        }
        None => {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{block_line} `[[allow]]` entry is missing required `owner`"
            ));
            None
        }
    };

    let reason = match reason_value {
        Some((value, line)) => {
            if value.trim().is_empty() {
                violations.push(format!(
                    "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line} `reason` is blank; explain why this matcher is exempt"
                ));
                None
            } else {
                Some(value)
            }
        }
        None => {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{block_line} `[[allow]]` entry is missing required `reason`"
            ));
            None
        }
    };

    if let (Some(matcher), Some(owner), Some(reason)) = (matcher, owner, reason) {
        entries.push(StaticLanguageAllowEntry {
            matcher,
            owner,
            reason,
        });
    }
}

fn validate_static_language_path(path: &str, line_number: usize) -> Result<(), String> {
    if path.is_empty() {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `path` is empty"
        ));
    }
    if path.contains('\\') {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `path` `{path}` uses backslashes; use `/` separators"
        ));
    }
    if is_absolute_path_like(path) {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `path` `{path}` is absolute; entries must be repository-relative"
        ));
    }
    if path.contains('*') || path.contains('?') {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `path` `{path}` contains glob characters; use `glob = ...` instead"
        ));
    }
    Ok(())
}

fn validate_static_language_glob(glob: &str, line_number: usize) -> Result<(), String> {
    if glob.is_empty() {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `glob` is empty"
        ));
    }
    if glob.contains('\\') {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `glob` `{glob}` uses backslashes; use `/` separators"
        ));
    }
    if is_absolute_path_like(glob) {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `glob` `{glob}` is absolute; entries must be repository-relative"
        ));
    }
    if !STATIC_LANGUAGE_ALLOWED_GLOBS.contains(&glob) {
        return Err(format!(
            "{STATIC_LANGUAGE_ALLOWLIST_PATH}:{line_number} `glob` `{glob}` is not in the scoped set; current allowed globs: {}",
            STATIC_LANGUAGE_ALLOWED_GLOBS.join(", ")
        ));
    }
    Ok(())
}

fn is_absolute_path_like(value: &str) -> bool {
    if value.starts_with('/') {
        return true;
    }
    let bytes = value.as_bytes();
    bytes.len() >= 2 && bytes[1] == b':' && bytes[0].is_ascii_alphabetic()
}

fn load_static_language_allowlist() -> Result<Vec<StaticLanguageAllowEntry>, Vec<String>> {
    if Path::new(STATIC_LANGUAGE_ALLOWLIST_LEGACY_PATH).exists() {
        return Err(vec![format!(
            "{STATIC_LANGUAGE_ALLOWLIST_LEGACY_PATH} still exists; the static-language allowlist moved to {STATIC_LANGUAGE_ALLOWLIST_PATH}. Delete the legacy `.txt` file to avoid split-brain policy."
        )]);
    }
    let path = Path::new(STATIC_LANGUAGE_ALLOWLIST_PATH);
    let text = read_text_lossy(path).map_err(|err| vec![err])?;
    let (entries, mut violations) = parse_static_language_allowlist(&text);
    for entry in &entries {
        if let StaticLanguageMatcher::Path(value) = &entry.matcher
            && !Path::new(value).exists()
        {
            violations.push(format!(
                "{STATIC_LANGUAGE_ALLOWLIST_PATH} matcher `{value}` does not exist on disk"
            ));
        }
    }
    if violations.is_empty() {
        Ok(entries)
    } else {
        Err(violations)
    }
}

fn static_language_allowlist_covers(allowlist: &[StaticLanguageAllowEntry], path: &str) -> bool {
    allowlist.iter().any(|entry| match &entry.matcher {
        StaticLanguageMatcher::Path(value) => value == path,
        StaticLanguageMatcher::Glob(value) => glob_matches(value, path),
    })
}

fn should_scan_static_language_path(allowlist: &[StaticLanguageAllowEntry], path: &str) -> bool {
    is_static_language_candidate(path) && !static_language_allowlist_covers(allowlist, path)
}

fn glob_parts_match(pattern: &[&str], path: &[&str]) -> bool {
    if pattern.is_empty() {
        return path.is_empty();
    }
    if pattern[0] == "**" {
        return glob_parts_match(&pattern[1..], path)
            || (!path.is_empty() && glob_parts_match(pattern, &path[1..]));
    }
    if path.is_empty() {
        return false;
    }
    segment_matches(pattern[0], path[0]) && glob_parts_match(&pattern[1..], &path[1..])
}

fn segment_matches(pattern: &str, value: &str) -> bool {
    let pattern_chars = pattern.chars().collect::<Vec<_>>();
    let value_chars = value.chars().collect::<Vec<_>>();
    segment_parts_match(&pattern_chars, &value_chars)
}

fn segment_parts_match(pattern: &[char], value: &[char]) -> bool {
    if pattern.is_empty() {
        return value.is_empty();
    }
    if pattern[0] == '*' {
        return segment_parts_match(&pattern[1..], value)
            || (!value.is_empty() && segment_parts_match(pattern, &value[1..]));
    }
    !value.is_empty() && pattern[0] == value[0] && segment_parts_match(&pattern[1..], &value[1..])
}

fn parse_git_stage_line(line: &str) -> Option<(&str, &str)> {
    let mut parts = line.split_whitespace();
    let mode = parts.next()?;
    let _object_type = parts.next()?;
    let _hash = parts.next()?;
    let stage_and_path = line.split('\t').nth(1)?;
    Some((mode, stage_and_path))
}

fn extract_workflow_run_blocks(text: &str) -> Vec<RunBlock> {
    let lines = text.lines().collect::<Vec<_>>();
    let mut blocks = Vec::new();
    let mut idx = 0usize;
    while idx < lines.len() {
        let line = lines[idx];
        let trimmed = line.trim_start();
        if let Some(rest) = workflow_run_value(trimmed) {
            let indent = line.len() - trimmed.len();
            let run_value = rest.trim();
            if run_value == "|" || run_value == ">" || run_value == "|-" || run_value == ">-" {
                let mut block_lines = Vec::new();
                let mut next_idx = idx + 1;
                while next_idx < lines.len() {
                    let next = lines[next_idx];
                    let next_trimmed = next.trim_start();
                    let next_indent = next.len() - next_trimmed.len();
                    if !next_trimmed.is_empty() && next_indent <= indent {
                        break;
                    }
                    block_lines.push(next_trimmed.to_string());
                    next_idx += 1;
                }
                let non_empty_lines = block_lines
                    .iter()
                    .filter(|value| !value.trim().is_empty())
                    .count();
                blocks.push(RunBlock {
                    line_number: idx + 1,
                    non_empty_lines,
                    text: block_lines.join("\n"),
                });
                idx = next_idx;
                continue;
            }
            blocks.push(RunBlock {
                line_number: idx + 1,
                non_empty_lines: usize::from(!run_value.is_empty()),
                text: run_value.to_string(),
            });
        }
        idx += 1;
    }
    blocks
}

fn workflow_run_value(trimmed_line: &str) -> Option<&str> {
    trimmed_line
        .strip_prefix("run:")
        .or_else(|| trimmed_line.strip_prefix("- run:"))
}

fn forbidden_static_terms() -> Vec<String> {
    ["killed", "survived", "untested", "proven", "adequate"]
        .iter()
        .map(|value| value.to_string())
        .collect()
}

/// Inline marker that suppresses static-language violations for a single line —
/// finer-grained than a whole-file allowlist entry. It MUST be followed by a
/// reason so the suppression is reviewable and not a silent drive-by:
///   `<comment-prefix> ripr-allow: static-language: <reason>`
const STATIC_LANGUAGE_INLINE_ALLOW_MARKER: &str = "ripr-allow: static-language:";

/// True when the (already-lowercased) line carries the inline-allow marker
/// followed by a non-empty reason. A bare marker with no reason does NOT
/// suppress, so an intentional allow always records why.
fn line_has_static_language_inline_allow(lower_line: &str) -> bool {
    match lower_line.find(STATIC_LANGUAGE_INLINE_ALLOW_MARKER) {
        Some(index) => {
            let after = &lower_line[index + STATIC_LANGUAGE_INLINE_ALLOW_MARKER.len()..];
            !after.trim().is_empty()
        }
        None => false,
    }
}

/// A plain-English synonym hint for a prohibited static-language term, used to
/// speed fixes when the term appears in prose/comments rather than analyzer
/// output. The gate scans all tracked prose, not only output strings, so a hit
/// is often an innocent English word that just needs a neutral synonym.
fn static_language_synonym_hint(term: &str) -> &'static str {
    match term {
        "killed" => "removed/terminated",
        "survived" => "persisted/remained",
        "untested" => "unexercised/uncovered",
        "proven" => "demonstrated/established",
        "adequate" => "sufficient/enough",
        _ => "a neutral synonym",
    }
}

/// Build an actionable static-language violation: `path:line`, the offending
/// snippet, and a fix hint. The hint names the common confusion — the gate
/// scans all tracked prose, not just analyzer output — so a hit in a comment or
/// doc is fixed with a plain synonym, while a hit in real output must use the
/// approved exposure vocabulary.
fn static_language_violation_message(
    path: &str,
    line_number: usize,
    term: &str,
    line: &str,
) -> String {
    let trimmed = line.trim();
    let snippet = if trimmed.chars().count() > 80 {
        let mut shortened: String = trimmed.chars().take(77).collect();
        shortened.push_str("...");
        shortened
    } else {
        trimmed.to_string()
    };
    let hint = static_language_synonym_hint(term);
    format!(
        "{path}:{line_number} prohibited static-language term `{term}` in `{snippet}` \
— this gate scans all tracked prose, not just analyzer output. In output, use the \
approved exposure vocabulary (exposed/weakly_exposed/reachable_unrevealed/no_static_path/\
infection_unknown/propagation_unknown/static_unknown). In comments or docs, use a plain \
synonym (e.g. {hint}). To intentionally allow this line, append \
`{STATIC_LANGUAGE_INLINE_ALLOW_MARKER} <reason>`."
    )
}

fn forbidden_panic_patterns() -> Vec<String> {
    [
        concat!("unwrap", "("),
        concat!("expect", "("),
        concat!("panic", "!"),
        concat!("todo", "!"),
        concat!("unimplemented", "!"),
        concat!("unreachable", "!"),
    ]
    .iter()
    .map(|value| value.to_string())
    .collect()
}

fn contains_word(text: &str, word: &str) -> bool {
    let mut start = 0usize;
    while let Some(offset) = text[start..].find(word) {
        let idx = start + offset;
        let before = text[..idx].chars().next_back();
        let after = text[idx + word.len()..].chars().next();
        if !is_word_char(before) && !is_word_char(after) {
            return true;
        }
        start = idx + word.len();
    }
    false
}

fn is_word_char(value: Option<char>) -> bool {
    value
        .map(|ch| ch.is_ascii_alphanumeric() || ch == '_')
        .unwrap_or(false)
}

#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd)]
struct PanicFinding {
    path: String,
    line: usize,
    column: Option<usize>,
    family: String,
}

#[derive(Debug, Clone)]
struct PanicAllowEntry {
    path: String,
    line: usize,
    column: Option<usize>,
    family: String,
    classification: Option<String>,
    explanation: String,
}

#[derive(Debug, Clone)]
struct PanicFamilySelector {
    kind: String,
    container: Option<String>,
    callee: Option<String>,
    receiver_fingerprint: Option<String>,
    text_contains: Option<String>,
    snippet: Option<String>,
}

#[derive(Debug, Clone)]
struct PanicFamilyLastSeen {
    line: usize,
    column: Option<usize>,
}

#[derive(Debug, Clone)]
struct PanicAllowEntryV2 {
    id: Option<String>,
    path: String,
    family: String,
    classification: Option<String>,
    owner: Option<String>,
    explanation: String,
    expires: Option<String>,
    selector: Option<PanicFamilySelector>,
    last_seen: Option<PanicFamilyLastSeen>,
    count: Option<usize>,
}

#[derive(Debug, Clone, Eq, PartialEq, Ord, PartialOrd)]
struct SemanticPanicFinding {
    path: String,
    family: String,
    kind: String,
    line: usize,
    column: Option<usize>,
    container: Option<String>,
    callee: Option<String>,
    receiver_fingerprint: Option<String>,
    snippet_fingerprint: String,
}

fn panic_family_from_pattern(pattern: &str) -> &'static str {
    match pattern {
        s if s.contains("unwrap") => "unwrap",
        s if s.contains("expect") => "expect",
        s if s.contains("panic!") => "panic_macro",
        s if s.contains("todo!") => "todo",
        s if s.contains("unimplemented!") => "unimplemented",
        s if s.contains("unreachable!") => "unreachable",
        _ => "unknown",
    }
}

fn collect_panic_findings(root: &Path, patterns: &[String]) -> Result<Vec<PanicFinding>, String> {
    let mut findings = Vec::new();

    for path in collect_files(root)? {
        if path.extension().and_then(|value| value.to_str()) != Some("rs") {
            continue;
        }
        let normalized = normalize_path(&path);
        let text = read_text_lossy(&path)?;

        for (line_num, line) in text.lines().enumerate() {
            let line_number = line_num + 1;
            for pattern in patterns {
                let mut start = 0usize;
                while let Some(offset) = line[start..].find(pattern) {
                    let col = start + offset + 1;
                    findings.push(PanicFinding {
                        path: normalized.clone(),
                        line: line_number,
                        column: Some(col),
                        family: panic_family_from_pattern(pattern).to_string(),
                    });
                    start = col;
                }
            }
        }
    }

    findings.sort();
    Ok(findings)
}

fn collect_semantic_panic_findings(
    root: &Path,
    patterns: &[String],
) -> Result<Vec<SemanticPanicFinding>, String> {
    use ra_ap_syntax::{AstNode, Edition, SourceFile};

    let mut findings = Vec::new();

    for path in collect_files(root)? {
        if path.extension().and_then(|value| value.to_str()) != Some("rs") {
            continue;
        }
        let normalized = normalize_path(&path);
        let text = read_text_lossy(&path)?;

        let parse = SourceFile::parse(&text, Edition::Edition2024);
        let tree = parse.tree();
        let root_node = tree.syntax();
        extract_panic_calls_from_node(root_node, &text, &normalized, patterns, &mut findings);
    }

    findings.sort();
    Ok(findings)
}

fn extract_panic_calls_from_node(
    node: &ra_ap_syntax::SyntaxNode,
    text: &str,
    path: &str,
    patterns: &[String],
    findings: &mut Vec<SemanticPanicFinding>,
) {
    use ra_ap_syntax::ast::{self, AstNode};

    for child in node.children() {
        let matched = if let Some(call_expr) = ast::MethodCallExpr::cast(child.clone()) {
            call_expr.name_ref().and_then(|method_name| {
                let name = method_name.text().to_string();
                if pattern_matches_panic_call(patterns, &name) {
                    extract_call_metadata(call_expr.syntax(), text, path, &name, "method_call")
                } else {
                    None
                }
            })
        } else if let Some(call_expr) = ast::CallExpr::cast(child.clone()) {
            call_expr.expr().and_then(|expr| {
                let func_text = expr.syntax().text().to_string();
                let base_callee = base_name_from_callee_text(&func_text);
                if pattern_matches_panic_call(patterns, base_callee) {
                    extract_call_metadata(call_expr.syntax(), text, path, base_callee, "call")
                } else {
                    None
                }
            })
        } else if let Some(macro_call) = ast::MacroCall::cast(child.clone()) {
            macro_call
                .path()
                .and_then(|p| p.segment())
                .and_then(|path_seg| {
                    let name = path_seg
                        .name_ref()
                        .map(|n| n.text().to_string())
                        .unwrap_or_default();
                    let macro_name = format!("{}!", name);
                    if pattern_matches_panic_call(patterns, &macro_name) {
                        extract_call_metadata(
                            macro_call.syntax(),
                            text,
                            path,
                            &macro_name,
                            "macro_call",
                        )
                    } else {
                        None
                    }
                })
        } else {
            None
        };

        if let Some(finding) = matched {
            findings.push(finding);
        }

        extract_panic_calls_from_node(&child, text, path, patterns, findings);
    }
}

fn base_name_from_callee_text(callee_text: &str) -> &str {
    callee_text.rsplit("::").next().unwrap_or(callee_text)
}

fn pattern_matches_panic_call(patterns: &[String], text: &str) -> bool {
    for pattern in patterns {
        if pattern == text {
            return true;
        }
        let base = pattern.trim_end_matches('(').trim_end_matches('!');
        if base == text && !base.is_empty() {
            return true;
        }
    }
    false
}

fn extract_call_metadata(
    node: &ra_ap_syntax::SyntaxNode,
    text: &str,
    path: &str,
    family_name: &str,
    kind: &str,
) -> Option<SemanticPanicFinding> {
    let (line, column) = line_and_column_for_node(node, text);
    let family = panic_family_from_call_name(family_name).to_string();
    let snippet = node.text().to_string();
    let snippet_fingerprint = snippet.replace('\n', " ").trim().to_string();

    let receiver_fingerprint = if kind == "method_call" {
        extract_method_receiver_fingerprint(node)
    } else {
        None
    };

    Some(SemanticPanicFinding {
        path: path.to_string(),
        family,
        kind: kind.to_string(),
        line,
        column,
        container: extract_container_name(node),
        callee: Some(family_name.to_string()),
        receiver_fingerprint,
        snippet_fingerprint,
    })
}

fn extract_method_receiver_fingerprint(node: &ra_ap_syntax::SyntaxNode) -> Option<String> {
    use ra_ap_syntax::ast::{self, AstNode};

    let method_call = ast::MethodCallExpr::cast(node.clone())?;
    let receiver = method_call.receiver()?;
    let text = receiver.syntax().text().to_string();
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    Some(normalized)
}

fn line_and_column_for_node(node: &ra_ap_syntax::SyntaxNode, text: &str) -> (usize, Option<usize>) {
    let offset: usize = node.text_range().start().into();
    let mut line = 1;
    let mut col = 0;

    for (byte_idx, ch) in text.char_indices() {
        if byte_idx > offset {
            break;
        }
        if ch == '\n' {
            line += 1;
            col = 0;
        } else {
            col += 1;
        }
    }

    (line, Some(col))
}

fn panic_family_from_call_name(name: &str) -> &'static str {
    match name {
        "unwrap" => "unwrap",
        "expect" => "expect",
        "panic!" => "panic_macro",
        "todo!" => "todo",
        "unimplemented!" => "unimplemented",
        "unreachable!" => "unreachable",
        s if s.starts_with("unwrap") && s.ends_with('(') => "unwrap",
        s if s.starts_with("expect") && s.ends_with('(') => "expect",
        s if s.starts_with("panic") && s.ends_with('!') => "panic_macro",
        s if s.starts_with("todo") && s.ends_with('!') => "todo",
        s if s.starts_with("unimplemented") && s.ends_with('!') => "unimplemented",
        s if s.starts_with("unreachable") && s.ends_with('!') => "unreachable",
        _ => "unknown",
    }
}

fn extract_container_name(node: &ra_ap_syntax::SyntaxNode) -> Option<String> {
    use ra_ap_syntax::ast::{self, AstNode, HasName};

    let mut current = node.parent();
    while let Some(parent) = current {
        let result = (|| {
            if let Some(func) = ast::Fn::cast(parent.clone()) {
                return func.name().map(|n| n.text().to_string());
            }
            if let Some(impl_block) = ast::Impl::cast(parent.clone()) {
                return impl_block.self_ty().and_then(|t| {
                    if let ast::Type::PathType(pt) = t {
                        pt.path().and_then(|p| {
                            p.segment()
                                .and_then(|s| s.name_ref().map(|n| n.text().to_string()))
                        })
                    } else {
                        None
                    }
                });
            }
            None
        })();
        if result.is_some() {
            return result;
        }
        current = parent.parent();
    }
    None
}

fn semantic_selector_matches(
    selector: &PanicFamilySelector,
    finding: &SemanticPanicFinding,
) -> bool {
    let valid_kind = matches!(
        selector.kind.as_str(),
        "method_call" | "call" | "macro_call" | "string_literal"
    );
    if !valid_kind {
        return false;
    }

    if selector.kind == "string_literal" {
        if finding.kind != "string_literal" {
            return false;
        }
        return selector
            .text_contains
            .as_ref()
            .is_some_and(|tc| finding.snippet_fingerprint.contains(tc));
    }

    selector.kind == finding.kind
        && (selector.container.is_none()
            || finding.container.as_ref() == selector.container.as_ref())
        && (selector.callee.is_none() || finding.callee.as_ref() == selector.callee.as_ref())
        && (selector.receiver_fingerprint.is_none()
            || finding.receiver_fingerprint.as_ref() == selector.receiver_fingerprint.as_ref())
        && (selector.snippet.is_none()
            || selector
                .snippet
                .as_deref()
                .is_some_and(|s| finding.snippet_fingerprint.contains(s)))
}

#[derive(Default, Debug, Clone, Eq, PartialEq)]
struct NoPanicFamilyReport {
    allowed_findings: Vec<String>,
    advisory_drift: Vec<String>,
    stale_entries: Vec<String>,
    unallowed_findings: Vec<String>,
    warnings: Vec<String>,
    violations: Vec<String>,
}

#[derive(Debug, Clone, Eq, PartialEq)]
struct NoPanicAllowlistProposal {
    id: String,
    current_finding: String,
    path: String,
    family: String,
    kind: String,
    container: Option<String>,
    callee: Option<String>,
    receiver_fingerprint: Option<String>,
    text_contains: Option<String>,
    confidence: String,
    replaces_v1_entry: bool,
    existing_entry: String,
    old_coordinates: Option<String>,
    last_seen_line: usize,
    last_seen_column: Option<usize>,
    classification: Option<String>,
    owner: Option<String>,
    explanation: String,
    expires: Option<String>,
    warnings: Vec<String>,
}

fn evaluate_semantic_no_panic_policy(
    findings: &[SemanticPanicFinding],
    entries: &[PanicAllowEntryVersioned],
) -> NoPanicFamilyReport {
    let mut report = NoPanicFamilyReport::default();
    let mut match_counts_by_entry = vec![0usize; entries.len()];

    for finding in findings {
        let mut matched_entries = Vec::new();
        for (index, entry) in entries.iter().enumerate() {
            if panic_allow_entry_matches(entry, finding) {
                matched_entries.push(index);
                match_counts_by_entry[index] += 1;
            }
        }

        if matched_entries.is_empty() {
            let message = format!(
                "{} contains unallowed panic-family '{}'; add exact allowlist entry with explanation",
                semantic_panic_finding_label(finding),
                finding.family
            );
            report.unallowed_findings.push(message.clone());
            report.violations.push(message);
            continue;
        }

        let allowed_by = matched_entries
            .iter()
            .map(|index| panic_allow_entry_label(&entries[*index]))
            .collect::<Vec<_>>()
            .join(", ");
        report.allowed_findings.push(format!(
            "{} allowed by {}",
            semantic_panic_finding_label(finding),
            allowed_by
        ));

        if matched_entries.len() > 1 {
            let message = format!(
                "duplicate semantic identity detected: {} matched {} allowlist entries ({allowed_by})",
                semantic_panic_finding_label(finding),
                matched_entries.len()
            );
            report.warnings.push(message.clone());
            report.violations.push(message);
        }

        for index in matched_entries {
            if let PanicAllowEntryVersioned::V2(entry) = &entries[index]
                && let Some(last_seen) = &entry.last_seen
                && (last_seen.line != finding.line || last_seen.column != finding.column)
            {
                report.advisory_drift.push(format!(
                    "allowed by semantic selector; last_seen changed from {}:{} to {} ({})",
                    last_seen.line,
                    last_seen.column.unwrap_or(0),
                    semantic_panic_finding_label(finding),
                    panic_allow_entry_label(&entries[index])
                ));
            }
        }
    }

    let mut identity_to_entries = BTreeMap::<String, Vec<String>>::new();
    for (index, entry) in entries.iter().enumerate() {
        match entry {
            PanicAllowEntryVersioned::V1(v1) => {
                if match_counts_by_entry[index] == 0 {
                    let message = format!(
                        "stale allowlist entry: {}:{}:{:?} ({}) does not match any current finding",
                        v1.path, v1.line, v1.column, v1.family
                    );
                    report.stale_entries.push(message.clone());
                    report.violations.push(message);
                }
            }
            PanicAllowEntryVersioned::V2(v2) => {
                if let Some(selector) = &v2.selector {
                    identity_to_entries
                        .entry(semantic_selector_identity(v2, selector))
                        .or_default()
                        .push(panic_allow_entry_label(entry));
                }
                let expected = v2.count.unwrap_or(1);
                let actual = match_counts_by_entry[index];
                if actual == 0 {
                    let message = format!(
                        "stale semantic allowlist entry: {} selector does not match any current finding",
                        panic_allow_entry_label(entry)
                    );
                    report.stale_entries.push(message.clone());
                    report.violations.push(message);
                } else if actual < expected {
                    report.advisory_drift.push(format!(
                        "stale-count drift: {} expected entry match count {expected}, matched {actual} (entry match count shrank; debt moved or was removed)",
                        panic_allow_entry_label(entry)
                    ));
                } else if actual > expected {
                    let message = if expected == 1 {
                        format!(
                            "ambiguous semantic allowlist entry: {} matches {actual} current findings",
                            panic_allow_entry_label(entry)
                        )
                    } else {
                        format!(
                            "count exceeded: {} expected entry match count {expected}, matched {actual} (new panic-family call site under existing entry)",
                            panic_allow_entry_label(entry)
                        )
                    };
                    report.warnings.push(message.clone());
                    report.violations.push(message);
                }
            }
        }
    }

    for labels in identity_to_entries.values() {
        if labels.len() > 1 {
            let message = format!(
                "duplicate semantic allowlist identity detected: {}",
                labels.join(", ")
            );
            report.warnings.push(message.clone());
            report.violations.push(message);
        }
    }

    report.allowed_findings.sort();
    report.allowed_findings.dedup();
    report.advisory_drift.sort();
    report.advisory_drift.dedup();
    report.stale_entries.sort();
    report.stale_entries.dedup();
    report.unallowed_findings.sort();
    report.unallowed_findings.dedup();
    report.warnings.sort();
    report.warnings.dedup();
    report.violations.sort();
    report.violations.dedup();
    report
}

fn build_no_panic_allowlist_proposals(
    findings: &[SemanticPanicFinding],
    entries: &[PanicAllowEntryVersioned],
) -> Vec<NoPanicAllowlistProposal> {
    let mut proposals = Vec::new();
    let mut seen = BTreeSet::new();

    for entry in entries {
        match entry {
            PanicAllowEntryVersioned::V1(v1) => {
                let exact_matches = findings
                    .iter()
                    .filter(|finding| {
                        v1.path == finding.path
                            && v1.family == finding.family
                            && v1.line == finding.line
                            && (v1.column.is_none() || v1.column == finding.column)
                    })
                    .collect::<Vec<_>>();
                let (candidate_findings, coordinates_drifted) = if exact_matches.is_empty() {
                    (
                        findings
                            .iter()
                            .filter(|finding| {
                                v1.path == finding.path && v1.family == finding.family
                            })
                            .collect::<Vec<_>>(),
                        true,
                    )
                } else {
                    (exact_matches, false)
                };

                for finding in candidate_findings {
                    let mut proposal = proposal_from_finding(
                        finding,
                        Some(entry),
                        true,
                        Some(format!("{}:{}", v1.line, v1.column.unwrap_or(0))),
                        findings,
                    );
                    if coordinates_drifted {
                        proposal.confidence = "review".to_string();
                        proposal.warnings.push(
                            "v0.1 coordinates did not match a current finding; candidate matched by path and family".to_string(),
                        );
                    }
                    push_no_panic_allowlist_proposal(&mut proposals, &mut seen, proposal);
                }
            }
            PanicAllowEntryVersioned::V2(_) => {
                let matching_findings = findings
                    .iter()
                    .filter(|finding| panic_allow_entry_matches(entry, finding))
                    .collect::<Vec<_>>();
                for finding in matching_findings {
                    push_no_panic_allowlist_proposal(
                        &mut proposals,
                        &mut seen,
                        proposal_from_finding(finding, Some(entry), false, None, findings),
                    );
                }
            }
        }
    }

    proposals.sort_by(|left, right| {
        left.path
            .cmp(&right.path)
            .then(left.last_seen_line.cmp(&right.last_seen_line))
            .then(left.family.cmp(&right.family))
            .then(left.id.cmp(&right.id))
    });
    proposals
}

fn push_no_panic_allowlist_proposal(
    proposals: &mut Vec<NoPanicAllowlistProposal>,
    seen: &mut BTreeSet<String>,
    proposal: NoPanicAllowlistProposal,
) {
    let key = format!(
        "{}:{}:{}:{}",
        proposal.path,
        proposal.family,
        proposal.last_seen_line,
        proposal.last_seen_column.unwrap_or(0)
    );
    if seen.insert(key) {
        proposals.push(proposal);
    }
}

fn proposal_from_finding(
    finding: &SemanticPanicFinding,
    entry: Option<&PanicAllowEntryVersioned>,
    replaces_v1_entry: bool,
    old_coordinates: Option<String>,
    all_findings: &[SemanticPanicFinding],
) -> NoPanicAllowlistProposal {
    let mut warnings = no_panic_selector_proposal_warnings(finding);
    let selector = selector_from_semantic_panic_finding(finding);
    let selector_match_count = all_findings
        .iter()
        .filter(|candidate| {
            candidate.path == finding.path
                && candidate.family == finding.family
                && semantic_selector_matches(&selector, candidate)
        })
        .count();
    if selector_match_count != 1 {
        warnings.push(format!(
            "suggested selector matches {selector_match_count} current findings; review before adopting"
        ));
    }
    if let Some(PanicAllowEntryVersioned::V2(existing)) = entry {
        let existing_entry = PanicAllowEntryVersioned::V2(existing.clone());
        let existing_match_count = all_findings
            .iter()
            .filter(|candidate| panic_allow_entry_matches(&existing_entry, candidate))
            .count();
        if existing_match_count > 1 {
            warnings.push(format!(
                "existing selector matches {existing_match_count} current findings"
            ));
        }
        if existing.selector.as_ref().is_some_and(|existing_selector| {
            existing_selector.receiver_fingerprint.is_none()
                && selector.receiver_fingerprint.is_some()
        }) {
            warnings.push("proposal adds receiver_fingerprint to disambiguate".to_string());
        }
    }

    let confidence = if warnings.is_empty() && selector_match_count == 1 {
        "high"
    } else {
        "review"
    }
    .to_string();
    let (existing_entry, classification, owner, explanation, expires) = match entry {
        Some(PanicAllowEntryVersioned::V1(v1)) => (
            panic_allow_entry_label(&PanicAllowEntryVersioned::V1(v1.clone())),
            v1.classification.clone(),
            None,
            v1.explanation.clone(),
            None,
        ),
        Some(PanicAllowEntryVersioned::V2(v2)) => (
            panic_allow_entry_label(&PanicAllowEntryVersioned::V2(v2.clone())),
            v2.classification.clone(),
            v2.owner.clone(),
            v2.explanation.clone(),
            v2.expires.clone(),
        ),
        None => (
            "new finding".to_string(),
            None,
            None,
            "TODO: review why this panic-family call is allowed".to_string(),
            None,
        ),
    };

    NoPanicAllowlistProposal {
        id: proposal_id_for_finding(finding),
        current_finding: semantic_panic_finding_label(finding),
        path: finding.path.clone(),
        family: finding.family.clone(),
        kind: selector.kind,
        container: selector.container,
        callee: selector.callee,
        receiver_fingerprint: selector.receiver_fingerprint,
        text_contains: selector.text_contains,
        confidence,
        replaces_v1_entry,
        existing_entry,
        old_coordinates,
        last_seen_line: finding.line,
        last_seen_column: finding.column,
        classification,
        owner,
        explanation,
        expires,
        warnings,
    }
}

fn selector_from_semantic_panic_finding(finding: &SemanticPanicFinding) -> PanicFamilySelector {
    if finding.kind == "string_literal" {
        return PanicFamilySelector {
            kind: finding.kind.clone(),
            container: None,
            callee: None,
            receiver_fingerprint: None,
            text_contains: Some(finding.snippet_fingerprint.clone()),
            snippet: None,
        };
    }

    PanicFamilySelector {
        kind: finding.kind.clone(),
        container: finding.container.clone(),
        callee: finding.callee.clone(),
        receiver_fingerprint: finding.receiver_fingerprint.clone(),
        text_contains: None,
        snippet: None,
    }
}

fn no_panic_selector_proposal_warnings(finding: &SemanticPanicFinding) -> Vec<String> {
    let mut warnings = Vec::new();
    if finding.kind == "string_literal" {
        if finding.snippet_fingerprint.trim().is_empty() {
            warnings.push("string_literal proposal has empty text fragment".to_string());
        }
        return warnings;
    }

    if finding
        .container
        .as_ref()
        .is_none_or(|value| value.trim().is_empty())
    {
        warnings.push("finding has no stable container".to_string());
    }
    if finding
        .container
        .as_ref()
        .is_some_and(|container| container.starts_with("closure_"))
    {
        warnings.push("finding uses unstable synthetic closure container".to_string());
    }
    if finding
        .callee
        .as_ref()
        .is_none_or(|value| value.trim().is_empty())
    {
        warnings.push("finding has no exact callee".to_string());
    }
    warnings
}

fn proposal_id_for_finding(finding: &SemanticPanicFinding) -> String {
    format!(
        "proposal-{}-{}-{}",
        no_panic_proposal_id_fragment(&finding.path),
        finding.family,
        finding.line
    )
}

fn no_panic_proposal_id_fragment(value: &str) -> String {
    let mut fragment = value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>();
    while fragment.contains("--") {
        fragment = fragment.replace("--", "-");
    }
    fragment.trim_matches('-').to_string()
}

fn render_no_panic_allowlist_proposals_markdown(proposals: &[NoPanicAllowlistProposal]) -> String {
    let mut body = String::new();
    body.push_str("# No-Panic Allowlist Proposals\n\n");
    body.push_str("Status: review-only\n\n");
    body.push_str("These proposals are generated hints. They do not rewrite the canonical allowlist and must be reviewed before adoption.\n\n");
    body.push_str(&format!("Candidates: {}\n\n", proposals.len()));
    if proposals.is_empty() {
        body.push_str("No matching allowlist entries need migration proposals.\n");
        return body;
    }

    for proposal in proposals {
        body.push_str(&format!("## {}\n\n", proposal.id));
        body.push_str(&format!(
            "- Current finding: `{}`\n",
            proposal.current_finding
        ));
        body.push_str(&format!("- Confidence: `{}`\n", proposal.confidence));
        body.push_str(&format!(
            "- Replaces v0.1 entry: `{}`\n",
            proposal.replaces_v1_entry
        ));
        body.push_str(&format!(
            "- Existing entry: `{}`\n",
            proposal.existing_entry
        ));
        body.push_str(&format!(
            "- Old coordinates: `{}`\n",
            proposal
                .old_coordinates
                .as_deref()
                .unwrap_or("not applicable")
        ));
        body.push_str(&format!(
            "- New `last_seen`: `{}:{}`\n",
            proposal.last_seen_line,
            proposal.last_seen_column.unwrap_or(0)
        ));
        body.push_str(&format!("- Reason: {}\n", proposal.explanation));
        body.push_str("- Suggested selector:\n\n");
        body.push_str("```toml\n");
        body.push_str(&render_no_panic_selector_toml(proposal));
        body.push_str("```\n\n");
        if proposal.warnings.is_empty() {
            body.push_str("- Warnings: none\n\n");
        } else {
            body.push_str("- Warnings:\n");
            for warning in &proposal.warnings {
                body.push_str(&format!("  - {warning}\n"));
            }
            body.push('\n');
        }
    }
    body
}

fn render_no_panic_allowlist_proposals_toml(proposals: &[NoPanicAllowlistProposal]) -> String {
    let mut body = String::new();
    body.push_str("# Generated by `cargo xtask check-no-panic-family --propose`.\n");
    body.push_str("# Review-only: fill every TODO-* field before pasting any entry into\n");
    body.push_str("# policy/no-panic-allowlist.toml — the check-no-panic-family gate rejects\n");
    body.push_str("# entries that still contain TODO-* placeholders (#2090).\n");
    body.push_str("schema_version = \"0.3\"\n");
    body.push_str("policy = \"no-panic-allowlist\"\n");
    body.push_str("owner = \"core/policy\"\n");
    body.push_str("status = \"proposal\"\n\n");
    if proposals.is_empty() {
        body.push_str("# No migration proposals.\n");
        return body;
    }

    for proposal in proposals {
        body.push_str(&format!("# Proposal: {}\n", proposal.id));
        body.push_str(&format!(
            "# Current finding: {}\n",
            proposal.current_finding
        ));
        body.push_str(&format!("# Confidence: {}\n", proposal.confidence));
        body.push_str(&format!(
            "# Replaces v0.1 entry: {}\n",
            proposal.replaces_v1_entry
        ));
        if let Some(old_coordinates) = &proposal.old_coordinates {
            body.push_str(&format!("# Old coordinates: {old_coordinates}\n"));
        }
        if proposal.warnings.is_empty() {
            body.push_str("# Warnings: none\n");
        } else {
            body.push_str("# Warnings:\n");
            for warning in &proposal.warnings {
                body.push_str(&format!("# - {warning}\n"));
            }
        }
        body.push_str("[[allow]]\n");
        body.push_str(&format!(
            "id = \"{}\"\n",
            no_panic_toml_string(
                proposal
                    .owner
                    .as_deref()
                    .map_or("TODO-review-id", |_| proposal.id.as_str())
            )
        ));
        body.push_str(&format!(
            "path = \"{}\"\n",
            no_panic_toml_string(&proposal.path)
        ));
        body.push_str(&format!(
            "family = \"{}\"\n",
            no_panic_toml_string(&proposal.family)
        ));
        body.push_str(&format!(
            "classification = \"{}\"\n",
            no_panic_toml_string(
                proposal
                    .classification
                    .as_deref()
                    .unwrap_or("review_required")
            )
        ));
        body.push_str(&format!(
            "owner = \"{}\"\n",
            no_panic_toml_string(proposal.owner.as_deref().unwrap_or("TODO-owner"))
        ));
        body.push_str(&format!(
            "explanation = \"{}\"\n",
            no_panic_toml_string(&proposal.explanation)
        ));
        body.push_str(&format!(
            "expires = \"{}\"\n\n",
            no_panic_toml_string(proposal.expires.as_deref().unwrap_or("TODO-expiry"))
        ));
        body.push_str(&render_no_panic_selector_toml(proposal));
        body.push('\n');
    }
    body
}

fn render_no_panic_selector_toml(proposal: &NoPanicAllowlistProposal) -> String {
    let mut body = String::new();
    body.push_str("[allow.selector]\n");
    body.push_str(&format!(
        "kind = \"{}\"\n",
        no_panic_toml_string(&proposal.kind)
    ));
    if let Some(container) = &proposal.container {
        body.push_str(&format!(
            "container = \"{}\"\n",
            no_panic_toml_string(container)
        ));
    }
    if let Some(callee) = &proposal.callee {
        body.push_str(&format!("callee = \"{}\"\n", no_panic_toml_string(callee)));
    }
    if let Some(receiver_fingerprint) = &proposal.receiver_fingerprint {
        body.push_str(&format!(
            "receiver_fingerprint = \"{}\"\n",
            no_panic_toml_string(receiver_fingerprint)
        ));
    }
    if let Some(text_contains) = &proposal.text_contains {
        body.push_str(&format!(
            "text_contains = \"{}\"\n",
            no_panic_toml_string(text_contains)
        ));
    }
    body.push_str("\n[allow.last_seen]\n");
    body.push_str(&format!("line = {}\n", proposal.last_seen_line));
    if let Some(column) = proposal.last_seen_column {
        body.push_str(&format!("column = {column}\n"));
    }
    body
}

fn no_panic_toml_string(value: &str) -> String {
    let mut escaped = String::new();
    for ch in value.chars() {
        match ch {
            '\u{08}' => escaped.push_str("\\b"),
            '\t' => escaped.push_str("\\t"),
            '\n' => escaped.push_str("\\n"),
            '\u{0c}' => escaped.push_str("\\f"),
            '\r' => escaped.push_str("\\r"),
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            ch if ch <= '\u{1f}' || ch == '\u{7f}' => {
                escaped.push_str(&format!("\\u{:04X}", ch as u32));
            }
            ch => escaped.push(ch),
        }
    }
    escaped
}

fn panic_allow_entry_matches(
    entry: &PanicAllowEntryVersioned,
    finding: &SemanticPanicFinding,
) -> bool {
    match entry {
        PanicAllowEntryVersioned::V1(v1) => {
            v1.path == finding.path
                && v1.family == finding.family
                && v1.line == finding.line
                && (v1.column.is_none() || v1.column == finding.column)
        }
        PanicAllowEntryVersioned::V2(v2) => {
            v2.path == finding.path
                && v2.family == finding.family
                && v2
                    .selector
                    .as_ref()
                    .is_some_and(|selector| semantic_selector_matches(selector, finding))
        }
    }
}

fn semantic_selector_identity(entry: &PanicAllowEntryV2, selector: &PanicFamilySelector) -> String {
    format!(
        "path={}|family={}|kind={}|container={}|callee={}|receiver={}|text={}|snippet={}",
        entry.path,
        entry.family,
        selector.kind,
        selector.container.as_deref().unwrap_or(""),
        selector.callee.as_deref().unwrap_or(""),
        selector.receiver_fingerprint.as_deref().unwrap_or(""),
        selector.text_contains.as_deref().unwrap_or(""),
        selector.snippet.as_deref().unwrap_or("")
    )
}

fn panic_allow_entry_label(entry: &PanicAllowEntryVersioned) -> String {
    match entry {
        PanicAllowEntryVersioned::V1(v1) => format!(
            "{}:{}:{} ({})",
            v1.path,
            v1.line,
            v1.column.unwrap_or(0),
            v1.family
        ),
        PanicAllowEntryVersioned::V2(v2) => {
            let id = v2.id.as_deref().unwrap_or("unversioned");
            let selector = v2
                .selector
                .as_ref()
                .map(panic_selector_label)
                .unwrap_or_else(|| "selector=missing".to_string());
            format!("{id} {} ({}) {selector}", v2.path, v2.family)
        }
    }
}

fn panic_selector_label(selector: &PanicFamilySelector) -> String {
    format!(
        "selector={} container={} callee={} receiver={} text={} snippet={}",
        selector.kind,
        selector.container.as_deref().unwrap_or(""),
        selector.callee.as_deref().unwrap_or(""),
        selector.receiver_fingerprint.as_deref().unwrap_or(""),
        selector.text_contains.as_deref().unwrap_or(""),
        selector.snippet.as_deref().unwrap_or("")
    )
}

fn semantic_panic_finding_label(finding: &SemanticPanicFinding) -> String {
    format!(
        "{}:{}:{}",
        finding.path,
        finding.line,
        finding.column.unwrap_or(0)
    )
}

fn print_no_panic_family_report(report: &NoPanicFamilyReport) {
    let status = if report.violations.is_empty() {
        "pass"
    } else {
        "fail"
    };
    println!("Status: {status}");
    println!();
    print_report_section("Allowed findings", &report.allowed_findings);
    print_report_section("Advisory drift", &report.advisory_drift);
    print_report_section("Stale entries", &report.stale_entries);
    print_report_section("Unallowed findings", &report.unallowed_findings);
    print_report_section("Warnings", &report.warnings);
}

fn print_report_section(title: &str, items: &[String]) {
    println!("{title}:");
    if items.is_empty() {
        println!("- none");
    } else {
        for item in items {
            println!("- {item}");
        }
    }
    println!();
}

fn parse_no_panic_allowlist_toml(path: &str) -> Result<Vec<PanicAllowEntry>, String> {
    let text = read_text_lossy(Path::new(path))?;
    let mut entries = Vec::new();
    let mut in_allow_section = false;
    let mut current_entry = PanicAllowEntry {
        path: String::new(),
        line: 0,
        column: None,
        family: String::new(),
        classification: None,
        explanation: String::new(),
    };
    let mut has_entry_started = false;
    let mut entry_start_line = 0;

    for (line_num, line) in text.lines().enumerate() {
        let line_number = line_num + 1;
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if trimmed == "schema_version = \"0.1\"" {
            continue;
        }

        if trimmed == "[[allow]]" {
            if has_entry_started {
                validate_panic_allow_entry(&current_entry, path, entry_start_line)?;
                entries.push(current_entry.clone());
            }
            current_entry = PanicAllowEntry {
                path: String::new(),
                line: 0,
                column: None,
                family: String::new(),
                classification: None,
                explanation: String::new(),
            };
            has_entry_started = true;
            in_allow_section = true;
            entry_start_line = line_number;
            continue;
        }

        if !in_allow_section {
            return Err(format!(
                "{path}:{} unexpected content outside [[allow]] section",
                line_number
            ));
        }

        let Some((key, value)) = parse_toml_key_value(trimmed) else {
            return Err(format!(
                "{path}:{} invalid TOML syntax (expected key = value)",
                line_number
            ));
        };

        match key {
            "path" => current_entry.path = parse_string_value(value, path, line_number)?,
            "line" => current_entry.line = parse_usize_value(value, path, line_number)?,
            "column" => current_entry.column = Some(parse_usize_value(value, path, line_number)?),
            "family" => current_entry.family = parse_string_value(value, path, line_number)?,
            "classification" => {
                current_entry.classification = Some(parse_string_value(value, path, line_number)?)
            }
            "explanation" => {
                current_entry.explanation = parse_string_value(value, path, line_number)?
            }
            _ => {
                return Err(format!(
                    "{path}:{} unknown field '{key}' in [[allow]] section",
                    line_number
                ));
            }
        }
    }

    if has_entry_started {
        validate_panic_allow_entry(&current_entry, path, entry_start_line)?;
        entries.push(current_entry);
    }

    check_duplicate_panic_allow_entries(&entries, path)?;
    Ok(entries)
}

fn parse_toml_key_value(trimmed: &str) -> Option<(&str, &str)> {
    let equals_idx = trimmed.find('=')?;
    let key = trimmed[..equals_idx].trim();
    let value_part = trimmed[equals_idx + 1..].trim();
    Some((key, value_part))
}

fn parse_string_value(value: &str, path: &str, line_number: usize) -> Result<String, String> {
    let v = strip_toml_value_comment(value).trim();
    if v.starts_with('"') && v.ends_with('"') && v.len() >= 2 {
        Ok(unescape_toml_string(&v[1..v.len() - 1]))
    } else {
        Err(format!(
            "{path}:{} string value must be quoted (got: {value})",
            line_number
        ))
    }
}

fn strip_toml_value_comment(value: &str) -> &str {
    let mut in_double = false;
    let mut escaped = false;

    for (idx, ch) in value.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if in_double && ch == '\\' {
            escaped = true;
            continue;
        }
        if ch == '"' {
            in_double = !in_double;
            continue;
        }
        if ch == '#' && !in_double {
            return &value[..idx];
        }
    }

    value
}

fn unescape_toml_string(value: &str) -> String {
    let mut out = String::new();
    let mut chars = value.chars();

    while let Some(ch) = chars.next() {
        if ch != '\\' {
            out.push(ch);
            continue;
        }

        let Some(next) = chars.next() else {
            out.push('\\');
            break;
        };
        match next {
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            other => {
                out.push('\\');
                out.push(other);
            }
        }
    }

    out
}

fn parse_usize_value(value: &str, path: &str, line_number: usize) -> Result<usize, String> {
    let v = value.split('#').next().unwrap_or(value).trim();
    v.parse::<usize>()
        .map_err(|_err| format!("{path}:{} invalid number (got: {value})", line_number))
}

fn validate_panic_allow_entry(
    entry: &PanicAllowEntry,
    path: &str,
    line_number: usize,
) -> Result<(), String> {
    if entry.path.is_empty() {
        return Err(format!(
            "{path}:{} missing required field: path",
            line_number
        ));
    }
    if entry.line == 0 {
        return Err(format!(
            "{path}:{} missing required field: line",
            line_number
        ));
    }
    if entry.family.is_empty() {
        return Err(format!(
            "{path}:{} missing required field: family",
            line_number
        ));
    }
    if entry.explanation.is_empty() {
        return Err(format!(
            "{path}:{} missing required field: explanation",
            line_number
        ));
    }
    Ok(())
}

fn check_duplicate_panic_allow_entries(
    entries: &[PanicAllowEntry],
    path: &str,
) -> Result<(), String> {
    let mut seen = BTreeMap::new();
    for entry in entries {
        let key = (
            entry.path.clone(),
            entry.line,
            entry.column,
            entry.family.clone(),
        );
        if seen.contains_key(&key) {
            return Err(format!(
                "{path}: duplicate allowlist entry for {}:{}:{:?} ({})",
                entry.path, entry.line, entry.column, entry.family
            ));
        }
        seen.insert(key, entry.line);
    }
    Ok(())
}

fn check_old_panic_allowlist_exists() -> Result<(), String> {
    if Path::new(".ripr/no-panic-allowlist.txt").exists() {
        return Err(
            ".ripr/no-panic-allowlist.txt still exists; use .ripr/no-panic-allowlist.toml instead"
                .to_string(),
        );
    }
    Ok(())
}

#[derive(Debug, Clone)]
#[allow(
    clippy::large_enum_variant,
    reason = "V2 grows with exact-identity snippet/count fields; boxing is a post-0.5.1 refactor"
)]
enum PanicAllowEntryVersioned {
    V1(PanicAllowEntry),
    V2(PanicAllowEntryV2),
}

fn parse_no_panic_allowlist_toml_v2(path: &str) -> Result<Vec<PanicAllowEntryVersioned>, String> {
    let text = read_text_lossy(Path::new(path))?;
    let mut entries = Vec::new();
    let mut schema_version = "0.1".to_string();

    // Accumulated fields for current entry
    let mut entry_id: Option<String> = None;
    let mut entry_path = String::new();
    let mut entry_line: usize = 0;
    let mut entry_column: Option<usize> = None;
    let mut entry_family = String::new();
    let mut entry_classification: Option<String> = None;
    let mut entry_owner: Option<String> = None;
    let mut entry_explanation = String::new();
    let mut entry_expires: Option<String> = None;
    let mut selector_kind = String::new();
    let mut selector_container: Option<String> = None;
    let mut selector_callee: Option<String> = None;
    let mut selector_receiver_fingerprint: Option<String> = None;
    let mut selector_text_contains: Option<String> = None;
    let mut selector_snippet: Option<String> = None;
    let mut last_seen_line: usize = 0;
    let mut last_seen_column: Option<usize> = None;
    let mut entry_count: Option<usize> = None;

    let mut in_allow_section = false;
    let mut in_selector_section = false;
    let mut in_last_seen_section = false;
    let mut has_entry_started = false;
    let mut entry_start_line = 0;

    let flush_entry = |has_entry: bool,
                       e_id: &Option<String>,
                       e_path: &str,
                       e_line: usize,
                       e_column: Option<usize>,
                       e_family: &str,
                       e_classification: &Option<String>,
                       e_owner: &Option<String>,
                       e_explanation: &str,
                       e_expires: &Option<String>,
                       e_count: Option<usize>,
                       s_kind: &str,
                       s_container: &Option<String>,
                       s_callee: &Option<String>,
                       s_receiver_fp: &Option<String>,
                       s_text_contains: &Option<String>,
                       s_snippet: &Option<String>,
                       ls_line: usize,
                       ls_column: Option<usize>,
                       schema_version: &str,
                       path: &str,
                       start_line: usize|
     -> Result<Option<PanicAllowEntryVersioned>, String> {
        if !has_entry {
            return Ok(None);
        }
        if e_path.is_empty() {
            return Err(format!("{path}:{start_line} missing required field: path"));
        }
        if e_family.is_empty() {
            return Err(format!(
                "{path}:{start_line} missing required field: family"
            ));
        }
        if e_explanation.is_empty() {
            return Err(format!(
                "{path}:{start_line} missing required field: explanation"
            ));
        }
        if schema_version == "0.3" {
            if e_id.as_ref().is_none_or(|value| value.trim().is_empty()) {
                return Err(format!("{path}:{start_line} missing required field: id"));
            }
            if e_classification
                .as_ref()
                .is_none_or(|value| value.trim().is_empty())
            {
                return Err(format!(
                    "{path}:{start_line} missing required field: classification"
                ));
            }
            if e_owner.as_ref().is_none_or(|value| value.trim().is_empty()) {
                return Err(format!("{path}:{start_line} missing required field: owner"));
            }
            if e_expires
                .as_ref()
                .is_none_or(|value| value.trim().is_empty())
            {
                return Err(format!(
                    "{path}:{start_line} missing required field: expires"
                ));
            }
            if s_kind.is_empty() {
                return Err(format!(
                    "{path}:{start_line} schema 0.3 entries require [allow.selector]"
                ));
            }
        }

        if !s_kind.is_empty() {
            // Semantic entry with selector.
            let selector = PanicFamilySelector {
                kind: s_kind.to_string(),
                container: s_container.clone(),
                callee: s_callee.clone(),
                receiver_fingerprint: s_receiver_fp.clone(),
                text_contains: s_text_contains.clone(),
                snippet: s_snippet.clone(),
            };
            let last_seen = if ls_line > 0 {
                Some(PanicFamilyLastSeen {
                    line: ls_line,
                    column: ls_column,
                })
            } else {
                None
            };
            let entry = PanicAllowEntryV2 {
                id: e_id.clone(),
                path: e_path.to_string(),
                family: e_family.to_string(),
                classification: e_classification.clone(),
                owner: e_owner.clone(),
                explanation: e_explanation.to_string(),
                expires: e_expires.clone(),
                selector: Some(selector),
                last_seen,
                count: e_count,
            };
            validate_panic_allow_entry_v2(&entry, path, start_line, schema_version)?;
            Ok(Some(PanicAllowEntryVersioned::V2(entry)))
        } else if e_line > 0 {
            // v0.1 entry with line number
            let entry = PanicAllowEntry {
                path: e_path.to_string(),
                line: e_line,
                column: e_column,
                family: e_family.to_string(),
                classification: e_classification.clone(),
                explanation: e_explanation.to_string(),
            };
            validate_panic_allow_entry(&entry, path, start_line)?;
            Ok(Some(PanicAllowEntryVersioned::V1(entry)))
        } else {
            Err(format!(
                "{path}:{start_line} entry must have either a [allow.selector] or line number"
            ))
        }
    };

    for (line_num, line) in text.lines().enumerate() {
        let line_number = line_num + 1;
        let trimmed = line.trim().trim_start_matches('\u{feff}');

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        if let Some((key, value)) = parse_toml_key_value(trimmed)
            && key == "schema_version"
        {
            schema_version = parse_string_value(value, path, line_number)?;
            if schema_version != "0.1" && schema_version != "0.2" && schema_version != "0.3" {
                return Err(format!(
                    "{path}:{line_number} unsupported no-panic allowlist schema_version {schema_version:?}"
                ));
            }
            continue;
        }

        if !has_entry_started
            && matches!(
                parse_toml_key_value(trimmed).map(|(key, _value)| key),
                Some("policy" | "owner" | "status")
            )
        {
            continue;
        }

        if trimmed == "[allow.selector]" {
            in_selector_section = true;
            in_last_seen_section = false;
            in_allow_section = false;
            continue;
        }

        if trimmed == "[allow.last_seen]" {
            in_last_seen_section = true;
            in_selector_section = false;
            in_allow_section = false;
            continue;
        }

        if trimmed == "[[allow]]" {
            // Flush previous entry
            let result = flush_entry(
                has_entry_started,
                &entry_id,
                &entry_path,
                entry_line,
                entry_column,
                &entry_family,
                &entry_classification,
                &entry_owner,
                &entry_explanation,
                &entry_expires,
                entry_count,
                &selector_kind,
                &selector_container,
                &selector_callee,
                &selector_receiver_fingerprint,
                &selector_text_contains,
                &selector_snippet,
                last_seen_line,
                last_seen_column,
                &schema_version,
                path,
                entry_start_line,
            )?;
            if let Some(entry) = result {
                entries.push(entry);
            }

            // Reset all fields for new entry
            entry_id = None;
            entry_path = String::new();
            entry_line = 0;
            entry_column = None;
            entry_family = String::new();
            entry_classification = None;
            entry_owner = None;
            entry_explanation = String::new();
            entry_expires = None;
            selector_kind = String::new();
            selector_container = None;
            selector_callee = None;
            selector_receiver_fingerprint = None;
            selector_text_contains = None;
            selector_snippet = None;
            last_seen_line = 0;
            last_seen_column = None;
            entry_count = None;

            in_selector_section = false;
            in_last_seen_section = false;
            in_allow_section = true;
            has_entry_started = true;
            entry_start_line = line_number;
            continue;
        }

        if !in_allow_section && !in_selector_section && !in_last_seen_section {
            return Err(format!(
                "{path}:{line_number} unexpected content outside [[allow]] section"
            ));
        }

        let Some((key, value)) = parse_toml_key_value(trimmed) else {
            return Err(format!(
                "{path}:{line_number} invalid TOML syntax (expected key = value)"
            ));
        };

        if in_selector_section {
            match key {
                "kind" => {
                    selector_kind = parse_string_value(value, path, line_number)?;
                }
                "container" => {
                    selector_container = Some(parse_string_value(value, path, line_number)?);
                }
                "callee" => {
                    selector_callee = Some(parse_string_value(value, path, line_number)?);
                }
                "receiver_fingerprint" => {
                    selector_receiver_fingerprint =
                        Some(parse_string_value(value, path, line_number)?);
                }
                "text_contains" => {
                    selector_text_contains = Some(parse_string_value(value, path, line_number)?);
                }
                "snippet" => {
                    selector_snippet = Some(parse_string_value(value, path, line_number)?);
                }
                _ => {
                    return Err(format!(
                        "{path}:{line_number} unknown field '{key}' in [allow.selector] section"
                    ));
                }
            }
            continue;
        }

        if in_last_seen_section {
            match key {
                "line" => {
                    last_seen_line = parse_usize_value(value, path, line_number)?;
                }
                "column" => {
                    last_seen_column = Some(parse_usize_value(value, path, line_number)?);
                }
                _ => {
                    return Err(format!(
                        "{path}:{line_number} unknown field '{key}' in [allow.last_seen] section"
                    ));
                }
            }
            continue;
        }

        // In [[allow]] section
        match key {
            "id" => entry_id = Some(parse_string_value(value, path, line_number)?),
            "path" => entry_path = parse_string_value(value, path, line_number)?,
            "line" => entry_line = parse_usize_value(value, path, line_number)?,
            "column" => entry_column = Some(parse_usize_value(value, path, line_number)?),
            "family" => entry_family = parse_string_value(value, path, line_number)?,
            "classification" => {
                entry_classification = Some(parse_string_value(value, path, line_number)?)
            }
            "owner" => entry_owner = Some(parse_string_value(value, path, line_number)?),
            "explanation" => entry_explanation = parse_string_value(value, path, line_number)?,
            "expires" => entry_expires = Some(parse_string_value(value, path, line_number)?),
            "count" => entry_count = Some(parse_usize_value(value, path, line_number)?),
            _ => {
                return Err(format!(
                    "{path}:{line_number} unknown field '{key}' in [[allow]] section"
                ));
            }
        }
    }

    // Flush final entry
    let result = flush_entry(
        has_entry_started,
        &entry_id,
        &entry_path,
        entry_line,
        entry_column,
        &entry_family,
        &entry_classification,
        &entry_owner,
        &entry_explanation,
        &entry_expires,
        entry_count,
        &selector_kind,
        &selector_container,
        &selector_callee,
        &selector_receiver_fingerprint,
        &selector_text_contains,
        &selector_snippet,
        last_seen_line,
        last_seen_column,
        &schema_version,
        path,
        entry_start_line,
    )?;
    if let Some(entry) = result {
        entries.push(entry);
    }

    Ok(entries)
}

fn validate_panic_allow_entry_v2(
    entry: &PanicAllowEntryV2,
    path: &str,
    line_number: usize,
    schema_version: &str,
) -> Result<(), String> {
    if entry.path.is_empty() {
        return Err(format!("{path}:{line_number} missing required field: path"));
    }
    if entry.family.is_empty() {
        return Err(format!(
            "{path}:{line_number} missing required field: family"
        ));
    }
    if entry.explanation.is_empty() {
        return Err(format!(
            "{path}:{line_number} missing required field: explanation"
        ));
    }
    if schema_version == "0.3" {
        if entry
            .id
            .as_ref()
            .is_none_or(|value| value.trim().is_empty())
        {
            return Err(format!("{path}:{line_number} missing required field: id"));
        }
        if entry
            .classification
            .as_ref()
            .is_none_or(|value| value.trim().is_empty())
        {
            return Err(format!(
                "{path}:{line_number} missing required field: classification"
            ));
        }
        if entry
            .owner
            .as_ref()
            .is_none_or(|value| value.trim().is_empty())
        {
            return Err(format!(
                "{path}:{line_number} missing required field: owner"
            ));
        }
        if entry
            .expires
            .as_ref()
            .is_none_or(|value| value.trim().is_empty())
        {
            return Err(format!(
                "{path}:{line_number} missing required field: expires"
            ));
        }
    }
    // A pasted --propose entry is not policy (#2090): unfilled proposal
    // placeholders must fail the gate, not pass as reviewed data.
    for (field, value) in [
        ("id", entry.id.as_ref()),
        ("owner", entry.owner.as_ref()),
        ("expires", entry.expires.as_ref()),
    ] {
        if let Some(value) = value
            && value.starts_with("TODO")
        {
            return Err(format!(
                "{path}:{line_number} {field} contains an unfilled proposal placeholder \
                 ({value}); replace every TODO-* field from the --propose output with \
                 reviewed content before committing"
            ));
        }
    }
    if let Some(ref selector) = entry.selector {
        if selector.kind.is_empty() {
            return Err(format!(
                "{path}:{line_number} selector missing required field: kind"
            ));
        }
        let supported_kinds = ["method_call", "macro_call", "call", "string_literal"];
        if !supported_kinds.contains(&selector.kind.as_str()) {
            return Err(format!(
                "{path}:{line_number} invalid selector kind '{}' in {path}; expected one of: {}",
                selector.kind,
                supported_kinds.join(", ")
            ));
        }
        if selector.kind == "string_literal" && selector.text_contains.is_none() {
            return Err(format!(
                "{path}:{line_number} string_literal selector requires text_contains"
            ));
        }
        if matches!(
            selector.kind.as_str(),
            "method_call" | "macro_call" | "call"
        ) {
            if selector
                .container
                .as_ref()
                .is_none_or(|value| value.trim().is_empty())
            {
                return Err(format!(
                    "{path}:{line_number} {} selector requires container",
                    selector.kind
                ));
            }
            if selector
                .callee
                .as_ref()
                .is_none_or(|value| value.trim().is_empty())
            {
                return Err(format!(
                    "{path}:{line_number} {} selector requires callee",
                    selector.kind
                ));
            }
            if let Some(container) = selector.container.as_deref()
                && container.starts_with("closure_")
            {
                return Err(format!(
                    "{path}:{line_number} {} selector uses unstable synthetic container `{container}`",
                    selector.kind
                ));
            }
        }
    }
    Ok(())
}

fn strip_yaml_comment(line: &str) -> &str {
    let mut in_single = false;
    let mut in_double = false;
    let chars: Vec<char> = line.chars().collect();
    for idx in 0..chars.len() {
        match chars[idx] {
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => {
                let backslash_run = chars[..idx]
                    .iter()
                    .rev()
                    .take_while(|&&c| c == '\\')
                    .count();
                if backslash_run % 2 == 0 {
                    in_double = !in_double;
                }
            }
            '#' if !in_single && !in_double => return &line[..chars[idx].len_utf8() * idx],
            _ => {}
        }
    }
    line
}

fn active_yaml_lines(text: &str) -> Vec<String> {
    text.lines()
        .map(strip_yaml_comment)
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(str::to_owned)
        .collect()
}

fn has_active_line(lines: &[String], pattern: &str) -> bool {
    lines.iter().any(|line| line.contains(pattern))
}

fn forbids_active_line(lines: &[String], pattern: &str) -> bool {
    lines.iter().any(|line| line.contains(pattern))
}

const DROID_SAFE_ACTION: &str = "EffortlessMetrics/droid-action-safe";
const DROID_SAFE_ACTION_SHA: &str = "7c1377ccbacddc95560d1570547a5baa51de01ec";
const DROID_UNSAFE_UPSTREAM_ACTION: &str = "Factory-AI/droid-action";
const DROID_GH_CLI_ARCHIVE: &str = "gh_2.82.1_linux_amd64.tar.gz";
const DROID_GH_CLI_SHA256: &str =
    "afada88676dfccea384e6cc28ae990b3e31bbc55f9d75c4697f902c757fa462b";

fn check_droid_action_refs(violations: &mut Vec<String>, path_label: &str, text: &str) {
    for (line_number, line) in text.lines().enumerate() {
        let trimmed = line.trim();
        if trimmed.starts_with('#') {
            continue;
        }
        let after_comment = strip_yaml_comment(trimmed).trim();
        let after_uses = after_comment
            .strip_prefix("- uses: ")
            .or_else(|| after_comment.strip_prefix("uses: "));
        if let Some(after_uses) = after_uses
            && let Some(at_pos) = after_uses.find('@')
        {
            let action = &after_uses[..at_pos];
            let ref_part = after_uses[at_pos + 1..]
                .split_whitespace()
                .next()
                .unwrap_or("");
            if !(ref_part.len() == 40 && ref_part.chars().all(|c| c.is_ascii_hexdigit())) {
                violations.push(format!(
                    "{path_label}:{} action ref must use immutable commit SHA: {action}@{ref_part}",
                    line_number + 1
                ));
            }
            if action == DROID_UNSAFE_UPSTREAM_ACTION {
                violations.push(format!(
                    "{path_label}:{} must not use unsafe upstream Droid action for BYOK workflows: {action}@{ref_part}",
                    line_number + 1
                ));
            }
            if action.contains("droid-action")
                && !(action == DROID_SAFE_ACTION && ref_part == DROID_SAFE_ACTION_SHA)
            {
                violations.push(format!(
                    "{path_label}:{} Droid action must use approved safe action ref {DROID_SAFE_ACTION}@{DROID_SAFE_ACTION_SHA}",
                    line_number + 1
                ));
            }
        }
    }
}

fn check_droid_common(
    violations: &mut Vec<String>,
    path_label: &str,
    text: &str,
    require_same_repo_guard: bool,
    require_review_model: bool,
) {
    let lines = active_yaml_lines(text);

    if require_same_repo_guard
        && !has_active_line(&lines, "head.repo.full_name == github.repository")
    {
        violations.push(format!(
            "{path_label}: same-repo guard (head.repo.full_name == github.repository) is required"
        ));
    }

    if require_review_model && !has_active_line(&lines, "review_model: \"custom:MiniMax-M3-0\"") {
        violations.push(format!(
            "{path_label}: review_model must be custom:MiniMax-M3-0"
        ));
    }

    if !has_active_line(&lines, "security_model: \"custom:MiniMax-M3-0\"") {
        violations.push(format!(
            "{path_label}: security_model must be custom:MiniMax-M3-0"
        ));
    }

    if !has_active_line(&lines, "$HOME/.factory/settings.json") {
        violations.push(format!(
            "{path_label}: must write $HOME/.factory/settings.json"
        ));
    }

    if !has_active_line(&lines, "${MINIMAX_API_KEY}") {
        violations.push(format!(
            "{path_label}: must keep ${{MINIMAX_API_KEY}} literal in settings.json"
        ));
    }

    if forbids_active_line(&lines, "settings:") {
        violations.push(format!(
            "{path_label}: must not use the Droid Action settings: input for BYOK"
        ));
    }

    for anthropic_global in ["ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_BASE_URL"] {
        let empty_double_quoted = format!("{anthropic_global}: \"\"");
        let empty_single_quoted = format!("{anthropic_global}: ''");
        let has_empty_override = has_active_line(&lines, &empty_double_quoted)
            || has_active_line(&lines, &empty_single_quoted);
        let has_non_empty_override = lines.iter().any(|line| {
            line.starts_with(&format!("{anthropic_global}:"))
                && line != &empty_double_quoted
                && line != &empty_single_quoted
        });

        if !has_empty_override || has_non_empty_override {
            violations.push(format!(
                "{path_label}: must clear {anthropic_global} with an empty step env override"
            ));
        }
    }

    let lower_lines: Vec<String> = lines.iter().map(|l| l.to_ascii_lowercase()).collect();
    if has_active_line(&lower_lines, "show_full_output: true") {
        violations.push(format!("{path_label}: must not enable show_full_output"));
    } else if !has_active_line(&lower_lines, "show_full_output: false") {
        violations.push(format!(
            "{path_label}: must explicitly set show_full_output: false"
        ));
    }

    if has_active_line(&lower_lines, "upload_debug_artifacts: true") {
        violations.push(format!(
            "{path_label}: must not enable Droid debug artifact upload"
        ));
    } else if !has_active_line(&lower_lines, "upload_debug_artifacts: false") {
        violations.push(format!(
            "{path_label}: must explicitly set upload_debug_artifacts: false"
        ));
    }

    if !has_active_line(&lines, "command -v gh") {
        violations.push(format!(
            "{path_label}: must check for GitHub CLI before running Droid"
        ));
    }
    if !has_active_line(&lines, DROID_GH_CLI_ARCHIVE) {
        violations.push(format!(
            "{path_label}: must install pinned GitHub CLI archive {DROID_GH_CLI_ARCHIVE}"
        ));
    }
    if !has_active_line(&lines, DROID_GH_CLI_SHA256) {
        violations.push(format!(
            "{path_label}: must verify pinned GitHub CLI SHA256 {DROID_GH_CLI_SHA256}"
        ));
    }
    if !has_active_line(&lines, "$GITHUB_PATH") {
        violations.push(format!(
            "{path_label}: must add the pinned GitHub CLI bin directory to $GITHUB_PATH"
        ));
    }

    check_droid_action_refs(violations, path_label, text);
}

fn check_droid_security_scan_config(violations: &mut Vec<String>, path_label: &str, text: &str) {
    let lines = active_yaml_lines(text);

    if !has_active_line(&lines, "workflow_dispatch:") {
        violations.push(format!(
            "{path_label}: workflow_dispatch trigger is required"
        ));
    }

    if !has_active_line(&lines, "cron: \"0 8 * * 1\"") {
        violations.push(format!(
            "{path_label}: weekly Monday 08:00 UTC schedule is required"
        ));
    }

    if !has_active_line(&lines, "droid-security-scan-${{ github.repository }}") {
        violations.push(format!(
            "{path_label}: concurrency group must be repository-scoped"
        ));
    }

    if !has_active_line(&lines, "cancel-in-progress: false") {
        violations.push(format!(
            "{path_label}: concurrency cancel-in-progress must be false"
        ));
    }

    if !has_active_line(&lines, "MINIMAX_API_KEY: ${{ secrets.MINIMAX_API_KEY }}") {
        violations.push(format!(
            "{path_label}: MINIMAX_API_KEY must be job-level env"
        ));
    }

    if !has_active_line(&lines, "security_scan_schedule: true") {
        violations.push(format!("{path_label}: security_scan_schedule must be true"));
    }

    if !has_active_line(&lines, "security_scan_days: 7") {
        violations.push(format!("{path_label}: security_scan_days must be 7"));
    }

    if !has_active_line(&lines, "security_severity_threshold: medium") {
        violations.push(format!(
            "{path_label}: security_severity_threshold must be medium"
        ));
    }

    if !has_active_line(&lines, "security_block_on_critical: true") {
        violations.push(format!(
            "{path_label}: security_block_on_critical must be true"
        ));
    }

    if !has_active_line(&lines, "security_block_on_high: false") {
        violations.push(format!(
            "{path_label}: security_block_on_high must be false"
        ));
    }

    check_droid_common(violations, path_label, text, false, false);
}

fn check_droid_review_config_impl() -> Result<(), String> {
    let mut violations = Vec::new();

    let droid_review_path = ".github/workflows/droid-review.yml";
    let droid_path = ".github/workflows/droid.yml";
    let droid_security_scan_path = ".github/workflows/droid-security-scan.yml";

    if let Ok(text) = read_text_lossy(Path::new(droid_review_path)) {
        let lines = active_yaml_lines(&text);

        if !has_active_line(&lines, "opened")
            || !has_active_line(&lines, "synchronize")
            || !has_active_line(&lines, "ready_for_review")
            || !has_active_line(&lines, "reopened")
        {
            violations.push(format!(
                "{droid_review_path}: pull_request types must include opened, synchronize, ready_for_review, reopened"
            ));
        }

        if lines
            .iter()
            .any(|line| line.to_ascii_lowercase().contains("draft"))
            && lines
                .iter()
                .any(|line| line.contains("if:") && line.to_ascii_lowercase().contains("draft"))
        {
            violations.push(format!(
                "{droid_review_path}: must not filter out draft PRs"
            ));
        }

        if !has_active_line(&lines, "cancel-in-progress: false") {
            violations.push(format!(
                "{droid_review_path}: concurrency cancel-in-progress must be false"
            ));
        }

        if !has_active_line(
            &lines,
            "droid-review-${{ github.repository }}-${{ github.event.pull_request.number }}",
        ) {
            violations.push(format!(
                "{droid_review_path}: concurrency group must be per repository and PR number"
            ));
        }

        if !has_active_line(&lines, "automatic_review: true") {
            violations.push(format!(
                "{droid_review_path}: automatic_review must be true"
            ));
        }

        if !has_active_line(&lines, "automatic_security_review: true") {
            violations.push(format!(
                "{droid_review_path}: automatic_security_review must be true"
            ));
        }

        if !has_active_line(&lines, "review_depth: shallow") {
            violations.push(format!(
                "{droid_review_path}: review_depth must be shallow unless intentionally changed"
            ));
        }

        if !has_active_line(&lines, "MINIMAX_API_KEY: ${{ secrets.MINIMAX_API_KEY }}") {
            violations.push(format!(
                "{droid_review_path}: MINIMAX_API_KEY must be job-level env"
            ));
        }

        check_droid_common(&mut violations, droid_review_path, &text, true, true);
    } else {
        violations.push(format!("{droid_review_path}: file not found or unreadable"));
    }

    if let Ok(text) = read_text_lossy(Path::new(droid_path)) {
        let lines = active_yaml_lines(&text);

        if !has_active_line(&lines, "OWNER")
            || !has_active_line(&lines, "MEMBER")
            || !has_active_line(&lines, "COLLABORATOR")
        {
            violations.push(format!(
                "{droid_path}: trusted actor guard (OWNER, MEMBER, COLLABORATOR) is required"
            ));
        }

        check_droid_common(&mut violations, droid_path, &text, true, true);
    } else {
        violations.push(format!("{droid_path}: file not found or unreadable"));
    }

    if let Ok(text) = read_text_lossy(Path::new(droid_security_scan_path)) {
        check_droid_security_scan_config(&mut violations, droid_security_scan_path, &text);
    } else {
        violations.push(format!(
            "{droid_security_scan_path}: file not found or unreadable"
        ));
    }

    finish_policy_report(
        PolicyReportSpec {
            report_file: "droid-review-config.md",
            check: "check-droid-review-config",
            why_it_matters: "Droid workflows handle repository secrets and automated review or security output; invariant drift can expose secrets, break BYOK model selection, or degrade review quality.",
            fix_kind: FixKind::PolicyExceptionRequired,
            recommended_fixes: &[
                "Restore the required invariant in the workflow YAML.",
                "If the invariant is intentionally changed, update docs/agent-context/review-invariants.md and add an xtask exception only after repo review.",
            ],
            rerun_command: "cargo xtask check-droid-review-config",
            exception_template: None,
        },
        &violations,
    )
}

